irab/engine.py:
"""Layer [4]: the rules engine, v0 (PLAN.md §5–6).

Input: one sentence = a list of words from layer [1] (data/words/*.words.json).
Output per word: part of speech (UPOS), function, form, the rules that fired, a TLA lemma id.

Function labels (coarse, the Arabic name is what the report shows):
  VERB_HEAD فعل الجملة · SUBJ مبتدأ/فاعل · OBJ مفعول به · PRED خبر · GEN مضاف إليه · GEN_PART أداة إضافة ·
  ATTR نعت · APPOS بدل/لقب · POBJ مجرور · ADVERBIAL ظرف/شبه جملة · PARTICLE أداة · CIRC حال · SPEC تمييز · DATE تاريخ
"""
import json
from pathlib import Path

from irab.lexicon import Lexicon, skeleton

ROOT = Path(__file__).resolve().parent.parent
CLOSED = ROOT / "data" / "lexicon" / "closed_class.json"

TIER_WEIGHT = {"form": 1.0, "lemma": 0.6, "form+loose": 0.8, "lemma+loose": 0.5}
PERSON_HINTS = ("chief", "supervisor", "overseer", "leader", "servant", "ruler", "king", "official", "commander")
NOUNISH = {"NOUN", "PROPN", "TITLE"}
# v3: parts of the body after an adjective = the nfr ḥr construction (wmt jb, wd ḥr, jꜥ ḥr)
BODY = {"ḥr", "jb", "ḥꜣtj", "ꜥ", "rd", "ḏrt", "ꜥwj", "rdwj"}
# v4 (n): verbs that take a dative «to/for someone» after their object (ḏj.j mw n jb, jr bw-nfr n ḫꜣst)
DATIVE = {"rḏj", "rdj", "ḏj", "dj", "jr", "jrj", "ḏd"}
# v5: verbs whose object can be a sḏm.f clause (ḏd.n.f ꜥḥꜣ.f ḥnꜥ.j «he said he would fight with me»)
SAY = {"ḏd", "ḫmt", "kꜣ"}
SEE = {"mꜣ", "mꜣꜣ", "rḫ"}            # … and a bare verb + suffixed subject (mꜣ.n.f rwḏ ꜥwj.j)


def word_key(w):
    if w["lemma"]:
        return skeleton(w["lemma"])
    if w["kind"] == "date":
        return None
    return skeleton(w["morph"][0]["m"]) if w["morph"] else skeleton(w["surface"])


def suffix_types(w):
    """Suffix types; an ambiguous final .n (sḏm.n.f or 'our') counts as sḏm.n here — the engine only asks
    about it on verbs, and reading it as a pronoun too would invent a pronoun subject (sb.n ḥm.f)."""
    out = []
    for m in w["morph"][1:]:
        t = m["type"]
        if isinstance(t, list):
            # v7: a second ambiguous .n after the sḏm.n one is the 1pl suffix «we» (pḥ.n.n «we reached»)
            if "sdm.n" in t and "sdm.n" in out:
                t = "pron.1pl"
            else:
                t = "sdm.n" if "sdm.n" in t else t[0]
        out.append(t)
    return out


def ambiguous_n(w):
    """True if the word ends in a .n that could be sḏm.n or the 1pl suffix."""
    return any(isinstance(m["type"], list) and "pron.1pl" in m["type"] for m in w["morph"][1:])


class Tag:
    """What layer [4] knows about one word before reading the sentence."""

    def __init__(self, w, lex, closed):
        self.w = w
        self.key = word_key(w)
        self.sufs = suffix_types(w)
        self.has_n = "sdm.n" in self.sufs
        self.has_pron = any(s.startswith("pron.") for s in self.sufs)
        self.stative = any(s.startswith("stative") for s in self.sufs)          # v1 (cause 6): .kw
        self.passive = "passive" in self.sufs                                  # v4 (jw + verb): grg.tw, jr.tw
        # v2 (cause 5): a hyphenated compound without a seed lemma is looked up whole first (m-ẖnw, not ẖnw)
        whole = skeleton(w["surface"]) if "-" in w["surface"] and not w["lemma"] else None
        if whole and (whole in closed or lex.candidates(whole)):
            self.key = whole
        self.cands = lex.candidates(self.key) if self.key else []
        # v1 (cause 7): Hannig writes ṯ/ḏ where other editions write t/d (jsṯ = jst)
        entry = closed.get(self.key) or closed.get((self.key or "").replace("ṯ", "t").replace("ḏ", "d"))
        if not entry and self.has_n and not self.has_pron:      # v2 (cause 5): nḥm.n = the particle nḥmn
            entry = closed.get(skeleton(w["surface"]))
            if entry:
                self.has_n = False
        if entry and entry.get("bare_only") and self.sufs:
            entry = None
        self.entry = entry
        kind = w["kind"]
        if kind == "date":
            self.cls = "DATE"
        elif w["surface"].isdigit():                            # v7: mḥ 120, hrw 3
            self.cls = "NUM"
        elif self.key == "n" and self.has_pron:                 # v1 (cause 5): n.j, n.f = preposition
            self.cls = "PREP"
        elif kind == "genitive_particle":
            self.cls = "GENPART"
        elif kind in ("name", "place"):
            self.cls = "PROPN"
        elif kind == "title":
            self.cls = "TITLE"
        elif kind == "prep":
            self.cls = "PREP"
        elif kind == "noun":
            self.cls = "NOUN"
        elif entry:
            self.cls = entry["cls"]
        else:
            self.cls = "OPEN"
        self.upos_dist = self._upos_dist()
        self.direct_dist = self._upos_dist(direct_only=True)
        if self.cls == "OPEN" and whole and self.key == whole and self.top_upos == "ADP":
            self.cls = "PREP"                                           # v4: m-ḥꜣt, ḥrw-r — compound prepositions
        # v7: a lone ambiguous .n on a word the lexicon reads as a noun is «our», not sḏm.n (jswt.n, tꜣ.n, mšꜥ.n)
        dist = self.direct_dist or self.upos_dist
        if (self.has_n and self.cls in ("OPEN", "NOUN") and self.sufs.count("sdm.n") == 1 and ambiguous_n(w)
                and next(iter(dist), None) in ("NOUN", "PROPN") and dist.get("VERB", 0) < 0.15):
            self.sufs = ["pron.1pl" if s == "sdm.n" else s for s in self.sufs]
            self.has_n, self.has_pron, self.n_as_1pl = False, True, True

    def _upos_dist(self, direct_only=False):
        dist = {}
        for c in self.cands:
            if direct_only and "+strip" in c["via"]:
                continue
            via = c["via"].split("+strip")[0]
            w = TIER_WEIGHT.get(via, 0.5) * (0.4 if "+strip" in c["via"] else 1.0)
            dist[c["upos"]] = dist.get(c["upos"], 0) + w * (c["freq"] + 0.2)
        total = sum(dist.values()) or 1
        return {k: v / total for k, v in sorted(dist.items(), key=lambda x: -x[1])}

    @property
    def top_upos(self):
        return next(iter(self.upos_dist), None)

    def verbish(self, threshold=0.15):
        """Verb evidence: the sḏm.n marker, or VERB among the direct (tier 1–2) readings; ending-stripped
        readings only count when there is no direct reading at all (mnmnt 'cattle' is not mnmn 'move')."""
        if self.cls != "OPEN":
            return False
        if self.stative or self.passive:                         # .kw / .tj / .tw only exist on verbs
            return True
        # a suffix pronoun is itself morphological evidence, so then the stripped readings (gm.n → gmi̯) count too
        dist = self.upos_dist if self.has_pron else (self.direct_dist or self.upos_dist)
        return self.has_n or dist.get("VERB", 0) >= threshold or next(iter(dist), None) == "VERB"

    def narrative_infinitive(self):
        """v1 (cause 2): stem + t + suffix subject at the start of a clause, where the stem (± weak j) is a verb:
        jrt.j, rḏjt.j, ṯst.j — Allen §13.14.2, a new 'journal entry' even without a date."""
        if self.cls != "OPEN" or not self.has_pron or self.has_n or not (self.key or "").endswith("t"):
            return False
        # ⚠ a verb whose root itself ends in t (mwt.f «he dies») would be misread; the lexicon cannot tell yet
        # v2: the verb reading has to be direct or come from dropping the -t; one reached only by adding a weak
        # j is not enough (jt.f «his father» → ꞽṯi̯ «take» via jt+j)
        return any(c["upos"] == "VERB" and ("+strip" not in c["via"] or "-t" in c["via"]) for c in self.cands)

    def can_be(self, upos):
        return upos in self.upos_dist

    def adjectival(self, threshold=0.15):
        return self.cls == "OPEN" and (self.top_upos == "ADJ" or self.upos_dist.get("ADJ", 0) >= threshold)

    def nominal_upos(self):
        """Part of speech for a word in a nominal slot (object of a preposition, subject…)."""
        if self.cls == "PROPN":
            return "PROPN"
        for u in ("NOUN", "PROPN"):
            if u in self.upos_dist:
                return u
        return self.top_upos or "NOUN"

    def nounish(self):
        return self.cls in NOUNISH or (self.cls == "OPEN" and self.top_upos in ("NOUN", "PROPN", None))

    def lemma_for(self, upos):
        """Among the readings with this part of speech, the most used one (an ending-stripped reading
        weighs less); TLA phrasemes like rḏi̯+(ꞽꜣ.w) only when nothing else fits."""
        def weight(c):
            w = TIER_WEIGHT.get(c["via"].split("+strip")[0], 0.5) * (0.4 if "+strip" in c["via"] else 1.0)
            return w * (c["freq"] + 0.2)
        same = [c for c in self.cands if c["upos"] == upos]
        plain = [c for c in same if "+(" not in c.get("lemma", "")]
        pool = plain or same
        if pool:
            return max(pool, key=weight)["id"]
        return self.cands[0]["id"] if self.cands else None

    def royal_title(self):
        return self.cls == "TITLE" and (self.w["lemma"] or "").endswith("nswt")

    def person_like(self):
        for c in self.cands[:8]:
            if any(h in (c.get("senses") or "") for h in PERSON_HINTS):
                return True
        return False


class Engine:
    def __init__(self, lex=None):
        self.lex = lex or Lexicon()
        with open(CLOSED, encoding="utf8") as f:
            self.closed = json.load(f)["entries"]

    # ---- one sentence ------------------------------------------------------------------------
    def analyze(self, words, prev_was_date=False):
        tags = [Tag(w, self.lex, self.closed) for w in words]
        for t in tags:
            for c in t.cands:
                e = self.lex.lemma(c["id"])
                c["senses"], c["lemma"] = e["senses"].lower(), e["lemma"]
        self.t, self.out, self.prev_was_date = tags, [None] * len(tags), prev_was_date
        self.dative = False
        self._initial_particles()
        if all(t.cls == "DATE" for t in tags):
            for i in range(len(tags)):
                self._set(i, "NUM", "DATE", rules=["R11"])
        elif tags[0].cls == "TITLE" and not self._titled_subject():
            self._title_chain()
        else:
            self._clause(0)
        for i, o in enumerate(self.out):
            if o is None:
                self._set(i, self.t[i].top_upos or "X", "UNKNOWN")
        return self.out

    def _initial_particles(self):
        """v5: words that are particles only at the start of a clause, decided by what follows them:
        ntt «that» (after a noun it is the relative ntt) · jn interrogative (jn wj = the verb «bring») ·
        jr «if» (jr n.k = the imperative «make») · tr is the enclitic only when no genitive follows (tr n msyt)."""
        t = self.t
        for i, w in enumerate(t):
            nxt = t[i + 1] if i + 1 < len(t) else None
            if getattr(w, "n_as_1pl", False) and nxt is not None and nxt.nounish() and nxt.cls != "PREP":
                # v7: X.n + a noun is sḏm.n.f + its nominal subject (wꜥrt tn jrt.n bꜣk), not «our X»
                w.sufs = ["sdm.n" if s == "pron.1pl" else s for s in w.sufs]
                w.has_n, w.has_pron = True, any(s.startswith("pron.") for s in w.sufs)
            if w.key == "tr" and w.cls == "PART_ENCL" and nxt is not None and nxt.cls == "GENPART":
                w.cls = "OPEN"
            # v7: jn inside a clause before a noun is the preposition «by» (rḏj.kw r jw jn wꜣw)
            if w.key == "jn" and i > 0 and not w.sufs and nxt is not None and nxt.nounish():
                w.cls = "PREP"
                continue
            if i > 0 and t[i - 1].cls != "PART_INTRO":
                continue
            # v8: kꜣ «then» before a suffixed verb (kꜣ ꜥnḫ.j jm.f); ḥꜣ «would that» before n.j (ḥꜣ n.j šsp nb) —
            # elsewhere kꜣ is «bull»/«ka» and ḥꜣ the preposition «behind»
            if i == 0 and nxt is not None and not w.sufs and (
                    (w.key == "kꜣ" and nxt.cls == "OPEN" and nxt.has_pron and nxt.can_be("VERB"))
                    or (w.key == "ḥꜣ" and nxt.cls == "PREP" and nxt.has_pron)):
                w.cls = "PART_INTRO"
                continue
            # v7: jn + noun + verb = the participial statement (jn ḫt ḥwj n.j sj «it was the mast that broke it»)
            if (w.key == "jn" and i == 0 and not w.sufs and nxt is not None and nxt.nounish() and i + 2 < len(t)
                    and t[i + 2].cls == "OPEN" and t[i + 2].can_be("VERB")):
                w.cls = "PART_INTRO"
                continue
            if w.key == "ntt" and w.cls == "REL" and i == 0:
                w.cls = "PART_INTRO"
            elif w.key in ("jn", "jr") and not w.sufs and nxt is not None and i == 0 \
                    and nxt.cls not in ("PRON_DEP", "PREP") and not (w.key == "jn" and nxt.cls == "OPEN" and not nxt.sufs):
                w.cls = "PART_INTRO"

    def _set(self, i, upos, fn, form="", rules=(), note=""):
        t = self.t[i]
        upos_out = "NOUN" if upos == "TITLE" else upos
        if upos_out == "VERB" and fn in ("VERB_HEAD", "PRED", "OBJ") and (t.key or "") in DATIVE:
            self.dative = True
        self.out[i] = {"w_id": t.w["w_id"], "surface": t.w["surface"], "upos": upos_out, "fn": fn, "form": form,
                       "rules": list(rules), "lemma_id": t.lemma_for(upos_out), "note": note}

    def _free(self, i):
        return i < len(self.t) and self.out[i] is None

    # ---- R18: title chains -------------------------------------------------------------------
    def _title_chain(self):
        i, n = 0, len(self.t)
        while i < n:
            t = self.t[i]
            prev = self.t[i - 1] if i else None
            if t.cls == "PROPN" and prev is not None and self._genitive_name(prev, t):
                self._set(i, "PROPN", "GEN", rules=["R16"])
            elif t.cls in ("TITLE", "PROPN"):
                self._set(i, "PROPN" if t.cls == "PROPN" else "NOUN", "APPOS", rules=["R18"])
            elif t.cls == "PREP":
                self._set(i, "ADP", "ATTR", rules=["R23"])
                if self._free(i + 1):
                    self._set(i + 1, self.t[i + 1].top_upos or "NOUN", "POBJ", rules=["R23"])
                    i += 1
            elif t.cls == "GENPART":
                i = self._genitive(i)
                continue
            elif t.adjectival() and prev is not None:
                self._set(i, "ADJ", "ATTR", rules=["R19"])
            elif t.has_pron and t.can_be("VERB") and i == n - 1:
                self._set(i, "VERB", "VERB_HEAD", "sḏm.f", ["R08"], note="⚖ آلن: صلة «الذي يقول»")
            elif t.has_pron and t.can_be("VERB"):
                self._set(i, "VERB", "ATTR", "صيغة صلة", ["R32"])
            elif t.nounish() and prev is not None and prev.cls in ("TITLE", "OPEN") \
                    and self.out[i - 1]["fn"] in ("APPOS", "GEN", "POBJ"):
                self._set(i, "NOUN", "GEN", rules=["R16"])
            else:
                self._set(i, t.top_upos or "NOUN", "APPOS", rules=["R18"])
            i += 1

    def _titled_subject(self):
        """v2 (cause 4): title (+ names) + a bare verb + a preposition / the end = SUBJECT + stative,
        not a title chain (nswt-bjtj sḥtp-jb-rꜥ wḏꜣ.w r ꜣḫt)."""
        k = 0
        while k < len(self.t) and self.t[k].cls in ("TITLE", "PROPN"):
            k += 1
        if k >= len(self.t):
            return False
        v = self.t[k]
        return v.cls == "OPEN" and not v.sufs and v.can_be("VERB") \
            and (k + 1 == len(self.t) or self.t[k + 1].cls == "PREP")

    @staticmethod
    def _genitive_name(prev, t):
        """R16, not R17: a royal title + the king's name ('king's wife of Senwosret'),
        or a common noun + a place name ('land of the Tjemehu')."""
        return prev.royal_title() or (t.w["kind"] == "place" and prev.cls in ("OPEN", "NOUN"))

    # ---- clauses -----------------------------------------------------------------------------
    def _clause(self, i):
        n = len(self.t)
        # R04: introductory particles, then enclitics
        while i < n and self.t[i].cls == "PART_INTRO":
            if self.t[i].has_pron:                                      # v1 (cause 3): jw.f — the suffix is the subject
                self._set(i, "PART", "SUBJ", rules=["R04", "R07"])
                return self._predicate(i + 1)
            self._set(i, "PART", "PARTICLE", rules=["R04"])
            i += 1
        while i < n and (self.t[i].cls == "PART_ENCL" or (self.t[i].key == "r" and self.t[i].has_pron and i > 0
                                                          and self.t[i - 1].cls == "PART_INTRO")):
            self._set(i, "PART", "PARTICLE", rules=["R04"])
            i += 1
        if i >= n:
            return
        t = self.t[i]
        after_particle = i > 0 and self.t[i - 1].cls in ("PART_INTRO", "PART_ENCL")

        if self._pw_initial(i):                                         # v3 (cause 1): wꜥf ꜥb pw · wmt jb pw
            return

        if t.cls == "PROPN" and i + 2 == n and self.t[i + 1].key == "rn" and self.t[i + 1].has_pron:
            # v8 (R42): ḫw.n-jnpw rn.f «Khunanup was his name» — the name is the predicate, rn.f the subject
            self._set(i, "PROPN", "PRED", rules=["R42"])
            self._set(i + 1, "NOUN", "SUBJ", rules=["R42", "R01"])
            return

        if (i + 2 < n and self.t[i + 1].key == "pw" and self.t[i + 2].key in ("jr", "jrj") and self.t[i + 2].has_n
                and t.cls == "OPEN" and not t.sufs):
            # v8 (R43): hꜣt pw jr.n sḫtj pn r kmt «what the peasant did was to go down» — infinitive + pw +
            # the relative form jr.n with its subject
            self._set(i, "VERB", "PRED", "مصدر", ["R43", "R35"])
            self._set(i + 1, "PRON", "SUBJ", rules=["R35"])
            self._set(i + 2, "VERB", "ATTR", "صيغة صلة sḏm.n.f", ["R43", "R32"])
            j = i + 3
            if not self.t[i + 2].has_pron and j < n and self.t[j].nounish():
                self._set(j, self.t[j].nominal_upos(), "SUBJ", rules=["R43", "R32"])
                j = self._noun_phrase(j + 1)
            return self._rest(j, complete=True)

        if after_particle and self.t[i - 1].key == "jw" and t.cls == "OPEN" and not t.has_n and (t.passive or (
                t.has_pron and t.can_be("VERB") and i + 1 < n and self._argument(i + 1))):
            # v4 (jw + verb): jw grg.tw n.j · jw sꜣb.j rmṯt nbt — a verb right after jw, not a noun subject
            return self._verbal(i)

        if t.cls == "PRON_IND":                                         # R06
            self._set(i, "PRON", "SUBJ", rules=["R06"])
            if self._free(i + 1):
                p = self.t[i + 1]
                if p.cls == "OPEN" and not p.sufs and p.can_be("VERB") and p.top_upos == "VERB":
                    # v2 (cause 1): ntf dꜣr ḫꜣswt — independent pronoun + participle, the participle takes an object
                    self._set(i + 1, "VERB", "PRED", "اسم فاعل", ["R06", "R30"])
                    if i + 2 < n and self._free(i + 2) and self.t[i + 2].nounish():
                        self._set(i + 2, self.t[i + 2].nominal_upos(), "OBJ", rules=["R30"])
                        return self._rest(self._noun_phrase(i + 3), complete=True)
                else:
                    self._set(i + 1, "NOUN", "PRED", rules=["R06"])
            return self._rest(i + 2, complete=True)

        if t.cls == "PRON_DEP" and after_particle:                      # R07
            self._set(i, "PRON", "SUBJ", rules=["R07"])
            return self._predicate(i + 1)

        if t.cls == "NEG" or (t.cls == "GENPART" and t.key == "n" and i == 0):   # v1 (cause 4): n = nj at the start
            return self._negation(i)

        if after_particle and t.cls == "ADV" and i + 1 < n and self.t[i + 1].nounish() and self.t[i + 1].cls != "PREP":
            # v6: jw mjn jb.f jꜥ(w) — a fronted adverb, then a full clause (not «jw + adverb, subject left out»)
            self._set(i, t.entry["upos"], "ADVERBIAL", rules=["R25"])
            return self._clause(i + 1)

        if after_particle and t.cls in ("PREP", "ADV"):                # v2 (cause 2): jw mj sḫr nṯr — subject left out
            return self._predicate(i)

        if t.cls in ("PREP", "ADV"):                                    # v1 (cause 1): a unit that is an adjunct
            return self._rest(i, complete=True)

        if t.key == "ꜥḥꜥ" and t.has_n and i + 1 < n and self.t[i + 1].verbish():   # v2 (cause 8): ꜥḥꜥ.n sḏm.n.f
            self._set(i, "VERB", "PARTICLE", "ꜥḥꜥ.n (فعل مساعد)", ["R38"])
            return self._verbal(i + 1)

        if i == 0 and t.cls == "OPEN" and not t.sufs and t.can_be("VERB") and not t.adjectival() and i + 1 < n \
                and self.t[i + 1].cls == "PREP" and self.t[i + 1].has_pron:
            # v5: a bare verb opening a clause + n.k / n.f = the imperative (sḫꜣ n.k hrw, jr n.k jwt, hꜣ n.f)
            self._set(i, "VERB", "VERB_HEAD", "أمر", ["R39"])
            self._set(i + 1, "ADP", "ADVERBIAL", rules=["R24"])
            j = i + 2
            if j < n and self._argument(j):
                self._set(j, self.t[j].nominal_upos(), "OBJ", rules=["R39"])
                j = self._noun_phrase(j + 1, coord_fn="OBJ")
            return self._rest(j, complete=True)

        if t.key == "ptr" and i + 1 < n:                                # v5: ptr «what?» + its subject
            self._set(i, "PRON", "PRED", rules=["R41"])
            s_ = self.t[i + 1]
            if s_.verbish() and s_.has_n:                               # ptr jrt.n.k «what is it that you did»
                self._set(i + 1, "VERB", "SUBJ", "صيغة صلة", ["R41", "R32"])
                j = i + 2
            elif s_.cls == "OPEN" and not s_.sufs and s_.can_be("VERB"):  # ptr smn ḏyt — a participle
                self._set(i + 1, "VERB", "SUBJ", "اسم فاعل", ["R41", "R31"])
                j = i + 2
            else:
                self._set(i + 1, s_.nominal_upos(), "SUBJ", rules=["R41"])
                j = self._noun_phrase(i + 2)
            return self._rest(j, complete=True)

        if t.cls == "OPEN" and not t.sufs and i + 1 < n and (t.adjectival() or t.can_be("ADJ")):
            # v2 (cause 7): nfr ṯw ḥnꜥ.j — adjectival sentence. v4: also when ADJ is only one of the readings
            # (wr, ꜥšꜣ, ꜥꜣ), if the subject is clear: a suffixed noun, or one after n.f / an enclitic
            k = i + 1
            while k < n and (self.t[k].cls == "PART_ENCL" or (self.t[k].cls == "PREP" and self.t[k].has_pron)):
                k += 1
            s = self.t[k] if k < n else None
            gap = k > i + 1
            participle = s is not None and gap and s.cls == "OPEN" and not s.sufs and s.can_be("VERB")
            if s is not None and not (s.cls == "PRON_DEP" and not t.adjectival()) \
                    and (s.cls == "PRON_DEP" or (s.verbish() and s.has_n) or participle
                                  or (s.nounish() and (t.adjectival() or s.has_pron or gap))):
                self._set(i, "ADJ", "PRED", rules=["R36"])
                for m in range(i + 1, k):
                    if self.t[m].cls == "PART_ENCL":
                        self._set(m, "PART", "PARTICLE", rules=["R04"])
                    else:
                        self._set(m, "ADP", "ADVERBIAL", rules=["R24"])
                if s.cls == "PRON_DEP":
                    self._set(k, "PRON", "SUBJ", rules=["R36", "R07"])
                    j = k + 1
                elif s.verbish() and s.has_n:                           # nfr jrrt.n.sn: a relative form
                    self._set(k, "VERB", "SUBJ", "صيغة صلة", ["R36", "R32"])
                    j = k + 1
                elif participle and not s.nounish():                    # ꜥꜣ grt dmjt r.j
                    self._set(k, "VERB", "SUBJ", "اسم فاعل", ["R36", "R31"])
                    j = k + 1
                else:
                    self._set(k, s.nominal_upos(), "SUBJ", rules=["R36"])
                    j = self._noun_phrase(k + 1)
                return self._rest(j, complete=True)

        if t.stative:                                                   # v1 (cause 6): ḫn.kw r jw … — main predicate
            self._set(i, "VERB", "VERB_HEAD", "الفعل التام القديم", ["R12"])
            return self._rest(i + 1, complete=True)

        if t.narrative_infinitive():                                    # v1 (cause 2): jrt.j šmt …
            self._set(i, "VERB", "VERB_HEAD", "مصدر سردي", ["R11"])
            j = i + 1
            if j < len(self.t) and self._free(j) and (self.t[j].nounish() or self.t[j].verbish()) \
                    and not self.t[j].has_n and self.t[j].cls == "OPEN":
                self._set(j, self.t[j].nominal_upos() if not self.t[j].verbish() else "VERB", "OBJ", rules=["R11"])
                j = self._noun_phrase(j + 1)
            return self._rest(j, complete=True)

        if t.cls in ("OPEN", "NOUN") and t.has_pron and not t.has_n and t.can_be("NOUN") and i + 2 < n \
                and self.t[i + 1].key == "ḥr" and not self.t[i + 1].has_pron and self.t[i + 2].can_be("VERB"):
            # v6: rdwj.j ḥr hwhw · jb.j ḥr ḫrp.j — subject + ḥr + infinitive (Gardiner §§320–323), not a sḏm.f
            self._set(i, t.nominal_upos(), "SUBJ", rules=["R03"])
            return self._predicate(i + 1)

        if t.cls == "OPEN" and not t.has_n and t.can_be("VERB") and i + 1 < n \
                and (self.t[i + 1].cls == "PRON_DEP" or (t.has_pron and self.t[i + 1].has_n and self.t[i + 1].verbish())):
            # v3 (cause 2): a noun cannot be followed by a dependent pronoun or by a sḏm.n.f of its own —
            # so the first word is a sḏm.f even when the lexicon prefers a noun (mr sw njwt.f, ꜥḥꜣ.f ḫmt.n.f)
            return self._verbal(i)

        if t.verbish() and (t.has_n or t.has_pron or t.passive or self.prev_was_date):
            return self._verbal(i)                                      # v5: + passive .tw (sfṯ.tw r rꜣ ꜥbꜣw.k)

        if t.nounish() or t.cls in ("TITLE", "PROPN"):
            self._set(i, "PROPN" if t.cls == "PROPN" else t.nominal_upos(), "SUBJ", rules=["R03"])
            j = self._noun_phrase(i + 1)
            if self._pw_sentence(i, j):
                return
            if j >= n:
                last = self.out[n - 1]
                if n - 1 > i and last["fn"] == "GEN" and self.t[n - 1].can_be("VERB"):   # R13: … ḫtm.w
                    self._set(n - 1, "VERB", "PRED", "الفعل التام القديم", ["R12", "R13", "R15"])
                else:                                                   # only a noun phrase: apposition
                    self.out[i]["fn"], self.out[i]["rules"] = "APPOS", ["R17"]
                return
            return self._predicate(j)

        if t.verbish():
            return self._verbal(i)
        self._set(i, t.top_upos or "X", "UNKNOWN")
        return self._rest(i + 1, complete=False)

    def _pw_sentence(self, i, j):
        """v2 (cause 3): NOUN (phrase) + pw = a nominal sentence; pw is the subject (ḥḳꜣ pw, nṯr pw grt,
        nb sꜣt pw jḳr sḫrw). What follows pw is more predicate: adjectives, their specifications, enclitics."""
        if j >= len(self.t) or self.t[j].key != "pw" or not self._free(j):
            return False
        self.out[i]["fn"], self.out[i]["rules"] = "PRED", ["R35"]
        if self.t[i].entry:                                             # jšst «what?»
            self.out[i]["upos"] = self.t[i].entry["upos"]
        self._set(j, "PRON", "SUBJ", rules=["R35"])
        self._pw_tail(j + 1)
        return True

    def _pw_initial(self, i):
        """v3 (cause 1): an adjective or a participle + its specification / object + pw (the hymn style).
        ADJ + body part → nfr ḥr (R20: wmt jb pw) · participle + noun → its object (R30: wꜥf ꜥb pw).
        A plain noun head is left to the nominal path (R35), except nb before a noun = «lord of»."""
        n, h = len(self.t), self.t[i]
        k = next((m for m in range(i + 1, min(i + 4, n)) if self.t[m].key == "pw"), None)
        if k is None or h.cls not in ("OPEN", "NOUN") or h.has_pron \
                or any((m.cls not in ("OPEN", "NOUN") and m.key not in BODY) or m.has_pron for m in self.t[i + 1:k]):
            return False
        mid = self.t[i + 1:k]
        if h.key == "nb" and mid:                                       # nb jmꜣt pw: lord + genitive
            upos, form, mfn, mrules = "NOUN", "", "GEN", ["R16"]
        elif (mid and mid[0].key in BODY) or (h.adjectival() and h.top_upos != "VERB"):
            upos, form, mfn, mrules = "ADJ", "", "SPEC", ["R20"]
        elif h.top_upos == "VERB":
            upos, form, mfn, mrules = "VERB", "اسم فاعل", "OBJ", ["R30"]
        else:
            return False
        self._set(i, upos, "PRED", form, ["R35"])
        for m in range(i + 1, k):
            self._set(m, self.t[m].nominal_upos(), mfn, rules=mrules)
        self._set(k, "PRON", "SUBJ", rules=["R35"])
        self._pw_tail(k + 1)
        return True

    def _pw_tail(self, k):
        """What follows pw is more predicate: enclitics, a second participle with its object (jꜥ ḥr pw tšꜣ wpwt),
        adjectives with their specifications (nb sꜣt pw jḳr sḫrw)."""
        n = len(self.t)
        while k < n and self.t[k].cls == "PART_ENCL":
            self._set(k, "PART", "PARTICLE", rules=["R04"])
            k += 1
        p = self.t[k] if k < n else None
        if p is not None and self._free(k) and p.cls == "OPEN" and not p.sufs and p.top_upos == "VERB":
            self._set(k, "VERB", "PRED", "اسم فاعل", ["R35", "R30"])      # v3
            k += 1
            if k < n and self._free(k) and self._argument(k):
                self._set(k, self.t[k].nominal_upos(), "OBJ", rules=["R30"])
                k = self._noun_phrase(k + 1)
        self._rest(self._noun_phrase(k, loose_spec=True), complete=True)

    def _predicate(self, j):
        n = len(self.t)
        while j < n and self.t[j].cls == "PART_ENCL":
            self._set(j, "PART", "PARTICLE", rules=["R04"])
            j += 1
        if j >= n:
            return
        p = self.t[j]
        if p.key == "n" and j + 1 < n and self.t[j + 1].cls == "PRON_IND":   # v2 (cause 6): ḥꜣtj.j n ntf m ẖt.j
            self._set(j, "PART", "PARTICLE", rules=["R34"])
            self._set(j + 1, "PRON", "SUBJ", rules=["R34", "R06"], note="⚖ آلن §11.7: مبتدأ منفي")
            return self._predicate(j + 2)
        if p.cls == "ADV":                                              # v2 (cause 2/5): ntjw jm
            self._set(j, p.entry["upos"], "PRED", rules=["R03"])
            return self._rest(j + 1, complete=True)
        if p.cls == "OPEN" and not p.sufs and p.can_be("VERB") and j > 0 and self.t[j - 1].has_pron \
                and self.out[j - 1] and self.out[j - 1]["fn"] == "SUBJ":
            # v2 (cause 4): a noun with a suffix cannot take a direct genitive, so a verb reading = stative (jb.j ꜣhd.w)
            self._set(j, "VERB", "PRED", "الفعل التام القديم", ["R12", "R13"])
            return self._rest(j + 1, complete=True)
        if p.cls == "PREP":                                             # R03 / R05
            if p.key == "m" and j + 1 < n and self.t[j + 1].person_like():
                self._set(j, "ADP", "PRED", rules=["R05"])
                self._set(j + 1, "NOUN", "PRED", rules=["R05"])
            else:
                self._set(j, "ADP", "PRED", rules=["R03"])
                if self._free(j + 1):
                    o = self.t[j + 1]
                    inf = p.key in ("ḥr", "m") and o.cls == "OPEN" and o.top_upos == "VERB"   # v6: ḥr + infinitive
                    self._set(j + 1, "VERB" if inf else o.nominal_upos(), "POBJ", "مصدر" if inf else "", ["R03"])
            return self._rest(j + 2, complete=True)
        if p.has_pron and (p.verbish() or (p.cls == "OPEN" and p.can_be("VERB") and j + 1 < n and self._argument(j + 1))):
            # SUBJECT–sḏm.f · v4: also when the lexicon prefers a noun but an object follows (jw.j ḏj.j mw n jb)
            self._set(j, "VERB", "PRED", "sḏm.f", ["R08"], note="⚖ آلن: SUBJECT–sḏm.f / جاردنر §148")
            if j + 1 < n and self._argument(j + 1):
                self._set(j + 1, self.t[j + 1].nominal_upos(), "OBJ", rules=["R08"])
                return self._rest(self._noun_phrase(j + 2), complete=True)
            return self._rest(j + 1, complete=True)
        later = next((m for m in range(j + 1, n) if self.t[m].cls == "OPEN" and self.t[m].has_pron
                      and not self.t[m].has_n and self.t[m].can_be("VERB") and self.t[m - 1].cls != "PREP"), None)
        prep_later = next((m for m in range(j + 2, n) if self.t[m].cls == "PREP" and self.t[m].key in ("ḥr", "m")), None)
        if p.verbish() and not p.sufs and later is None and prep_later is not None and self._argument(j + 1):
            # v6: nṯr šꜣ wꜥrt tn ḥr sṯꜣ.j — participle + object, the predicate is the ḥr phrase that follows
            self._set(j, "VERB", "ATTR", "اسم فاعل", ["R30"])
            self._set(j + 1, self.t[j + 1].nominal_upos(), "OBJ", rules=["R30"])
            k = self._noun_phrase(j + 2)
            return self._predicate(k)
        if p.verbish() and not p.sufs and later is not None:
            # v4 (participles): wpwtj ḫdd … r ẖnw ꜣb.f ḥr.j — the finite verb comes later, so this one is a participle
            self._set(j, "VERB", "ATTR", "اسم فاعل", ["R30"])
            self._set(later, "VERB", "PRED", "sḏm.f", ["R08"], note="⚖ آلن: SUBJECT–sḏm.f / جاردنر §148")
            return self._rest(j + 1, complete=True)
        if p.verbish():                                                 # R12–R13 stative
            self._set(j, "VERB", "PRED", "الفعل التام القديم", ["R12", "R13", "R15"])
            return self._rest(j + 1, complete=True)
        return self._rest(j, complete=False)

    def _verbal(self, i):
        n, t = len(self.t), self.t[i]
        if self.prev_was_date and not t.has_pron and not t.has_n:      # R11
            self._set(i, "VERB", "VERB_HEAD", "مصدر", ["R11"])
            if self._free(i + 1) and self.t[i + 1].nounish():
                self._set(i + 1, "NOUN", "SUBJ", rules=["R11"])
                return self._rest(i + 2, complete=True)
            return self._rest(i + 1, complete=True)
        form, rule = ("sḏm.n.f", "R09") if t.has_n else ("sḏm.f", "R08")
        self._set(i, "VERB", "VERB_HEAD", form, [rule])
        subj_in_verb = t.has_pron
        j = i + 1
        while j < n and self.t[j].cls == "PART_ENCL":                  # v2 (cause 5): wnn jr.f tꜣ pf
            self._set(j, "PART", "PARTICLE", rules=["R04"])
            j += 1
        if j < n and self.t[j].cls == "PRON_DEP":
            r10 = not subj_in_verb and j + 1 < n and self.t[j + 1].nounish()
            self._set(j, "PRON", "OBJ", rules=["R10"] if r10 else [rule])
            j += 1
        c = self.t[j] if j < n else None
        if c is not None and self._free(j) and c.cls == "OPEN" and not c.has_n and c.can_be("VERB") and (
                (t.key in SAY and c.has_pron)
                or (t.key in SEE and not c.sufs and j + 1 < n and self.t[j + 1].has_pron and self.t[j + 1].nounish())):
            # v5: the object is a sḏm.f clause — ḏd.n.f ꜥḥꜣ.f ḥnꜥ.j · mꜣ.n.f rwḏ ꜥwj.j
            self._set(j, "VERB", "VERB_HEAD", "sḏm.f", ["R40"])
            k = j + 1
            if not c.has_pron and k < n:
                self._set(k, self.t[k].nominal_upos(), "SUBJ", rules=["R40"])
                k += 1
            elif k < n and self.t[k].cls == "PRON_DEP":
                self._set(k, "PRON", "OBJ", rules=["R40"])
                k += 1
            return self._rest(k, complete=True)
        if not subj_in_verb and j < n and self._argument(j):
            self._set(j, self.t[j].nominal_upos(), "SUBJ", rules=[rule] + (["R10"] if self.out[j - 1] and self.out[j - 1]["fn"] == "OBJ" else []))
            j = self._noun_phrase(j + 1)
        if j < n and self._argument(j) and not any(o and o["fn"] == "OBJ" for o in self.out[i + 1:j]):
            self._set(j, self.t[j].nominal_upos(), "OBJ", rules=[rule])
            j = self._noun_phrase(j + 1, coord_fn="OBJ")
        return self._rest(j, complete=True)

    def _argument(self, j):
        """v2 (cause 4): right after the verb, a bare word that can be a noun is an argument (gmḥ.n.j stjw,
        wn ḫprt), even if its top reading is a verb — the stative only comes after an adverbial."""
        t = self.t[j]
        return self._free(j) and (t.nounish() or (t.cls == "OPEN" and not t.sufs and t.can_be("NOUN")))

    def _negation(self, i):
        n, t = len(self.t), self.t[i]
        if i + 1 < n and self.t[i + 1].cls == "PRON_IND":
            # v6: n jnk js ḳꜣ sꜣ · n jnk tr smꜣ.f — nj (… js) + independent pronoun + predicate (Allen §11.5)
            self._set(i, "PART", "PARTICLE", rules=["R34"])
            self._set(i + 1, "PRON", "SUBJ", rules=["R06"])
            k = i + 2
            while k < n and self.t[k].cls == "PART_ENCL":
                self._set(k, "PART", "PARTICLE", rules=["R04"])
                k += 1
            if k < n and self.t[k].cls in ("PREP", "ADV"):
                return self._predicate(k)
            if k < n and self._free(k):
                q = self.t[k]
                self._set(k, "ADJ" if q.adjectival() else q.nominal_upos(), "PRED", rules=["R06"])
                k += 1
                if k < n and self._free(k) and q.adjectival() and self.t[k].nounish() and not self.t[k].has_pron:
                    self._set(k, "NOUN", "SPEC", rules=["R20"])        # ḳꜣ sꜣ «high of back»
                    k += 1
            return self._rest(k, complete=True)
        if t.key == "nj" and i + 1 < n and self.t[i + 1].key == "sp":   # R34
            self._set(i, "PART", "PARTICLE", rules=["R34"])
            self._set(i + 1, "NOUN", "PARTICLE", rules=["R34"])
            if i + 2 < n:
                self._set(i + 2, "VERB", "VERB_HEAD", "sḏm.f", ["R34"])
            return self._rest(i + 3, complete=True)
        if t.key in ("nj", "n") and i + 1 < n and self.t[i + 1].cls == "OPEN":   # v1 (cause 4): nj sḏm.f (+ complement)
            self._set(i, "PART", "PARTICLE", rules=["R34"])
            self._set(i + 1, "VERB", "VERB_HEAD", "sḏm.f", ["R34"])
            j = i + 2
            if j < n and self._free(j) and self.t[j].cls == "OPEN" and not self.t[j].has_pron:
                if j + 1 < n and self.t[j + 1].cls == "PRON_DEP" and self.t[j].can_be("VERB"):
                    # v2 (cause 1): nj rḫ.j jn wj — a participle as object, with its own object pronoun
                    self._set(j, "VERB", "OBJ", "اسم فاعل", ["R34", "R31"])
                    self._set(j + 1, "PRON", "OBJ", rules=["R31"])
                    return self._rest(j + 2, complete=True)
                self._set(j, "VERB" if self.t[j].verbish() else self.t[j].nominal_upos(), "OBJ", rules=["R34"])
                j += 1
            elif j < n and self._free(j) and self.t[j].nounish() and self.t[j].has_pron:
                # v2 (cause 2): nj sḏm.tw rn.j m rꜣ — the noun is the subject, what follows is an adjunct
                self._set(j, self.t[j].nominal_upos(), "SUBJ", rules=["R34"])
                j += 1
            return self._rest(j, complete=True)
        if t.key == "nn" and i + 1 < n and self.t[i + 1].verbish():   # R29
            self._set(i, "PART", "PARTICLE", rules=["R29"])
            self._set(i + 1, "VERB", "VERB_HEAD", "مصدر", ["R29"])
            return self._causative(i + 1) if self.t[i + 1].key == "rdjt" else self._rest(i + 2, complete=True)
        if t.key == "nn" and i + 2 < n and self.t[i + 1].cls == "OPEN" and self.t[i + 1].has_pron \
                and self.t[i + 1].can_be("VERB") and self._argument(i + 2):
            # v3 (cause 2): nn + sḏm.f + object (nn kꜣ.f ḫꜣswt) — a noun with a suffix would end the clause
            self._set(i, "PART", "PARTICLE", rules=["R34"])
            self._set(i + 1, "VERB", "VERB_HEAD", "sḏm.f", ["R34"])
            self._set(i + 2, self.t[i + 2].nominal_upos(), "OBJ", rules=["R34"])
            return self._rest(self._noun_phrase(i + 3), complete=True)
        self._set(i, "PART", "PARTICLE", rules=["R33"])                # R33
        if i + 1 < n:
            self._set(i + 1, "NOUN", "SUBJ", rules=["R33"])
        k = i + 2
        if k < n and self.t[k].cls == "OPEN" and not self.t[k].sufs and self.t[k].can_be("VERB"):
            self._set(k, "VERB", "CIRC", "الفعل التام القديم", ["R33", "R14"])   # v2 (cause 4): nn ky ḫpr.(w)
            k += 1
        return self._rest(k, complete=True)

    def _causative(self, i):
        """R28: rdj + sḏm.f — the second verb is a clause, its object pronoun comes before its subject."""
        n, j = len(self.t), i + 1
        if j < n and self.t[j].cls == "OPEN":
            self._set(j, "VERB", "VERB_HEAD", "sḏm.f", ["R28"])
            j += 1
            if j < n and self.t[j].cls == "PRON_DEP":
                self._set(j, "PRON", "OBJ", rules=["R10", "R28"])
                j += 1
            if j < n and self.t[j].nounish():
                self._set(j, "NOUN" if self.t[j].cls != "PROPN" else "PROPN", "SUBJ", rules=["R28"])
                j += 1
        return self._rest(j, complete=True)

    # ---- inside noun phrases -----------------------------------------------------------------
    def _prep_n(self, j):
        """v2 (cause 6): a lone n is the preposition «to», not the genitive particle, when there is no noun
        before it to own the genitive, or in X n X «from X to X» (rḏj.n wj ḫꜣst n ḫꜣst)."""
        if self.t[j].key != "n" or j == 0 or j + 1 >= len(self.t):
            return False
        before, after = self.t[j - 1], self.t[j + 1]
        o = self.out[j - 1]
        if o and o["fn"] in ("ADVERBIAL", "VERB_HEAD", "PARTICLE") or before.cls == "PREP":
            return True
        # v4 (n): after the object of a giving/doing verb = dative; after a noun with a suffix = «with/to»
        # (a suffixed noun does not take the indirect genitive in these texts: tꜣš.f n kt ḫꜣst)
        if o and self.dative and o["fn"] in ("SUBJ", "ATTR") and self.t[j + 1].nounish() and any(
                x and x["fn"] == "VERB_HEAD" and x["upos"] == "VERB" for x in self.out[:j]):
            return True                                                 # v8: ḏd.jn sḫtj pn n ḥmt.f «said … to his wife»
        if o and (self.dative and o["fn"] == "OBJ" or before.has_pron and o["fn"] == "POBJ"):
            return True
        if self._sdmt(j + 1):                                           # v7: ḏꜥ n jjt «a storm before it came»
            return True
        return bool(before.key) and before.key == after.key

    def _sdmt(self, k):
        """v7: n + sḏmt.f «before he …» — a verb whose form ends in t (jjt, ḫprt.f). ⚖ Allen §19.14 reads this
        n as the negation nj; the gold here (and Nederhof's translation) reads «before», so it stays an adjunct."""
        if k >= len(self.t):
            return False
        v = self.t[k]
        after = self.t[k + 1] if k + 1 < len(self.t) else None
        return (v.cls == "OPEN" and not v.has_n and (v.w["morph"][0]["m"] if v.w["morph"] else "").endswith("t")
                and v.top_upos == "VERB" and not v.can_be("PROPN")              # not rꜣ n kmt
                and not (after is not None and after.cls == "PREP"))            # not n wnt ḥnꜥ.f (a participle)

    def _genitive(self, i):
        self._set(i, "ADJ", "GEN_PART", rules=["R02"])
        if self._free(i + 1):
            nxt = self.t[i + 1]
            after = self.t[i + 2] if i + 2 < len(self.t) else None             # v4: n wnt ḥnꜥ.f — a participle
            participle = nxt.cls == "OPEN" and not nxt.sufs and nxt.top_upos == "VERB" \
                    and after is not None and after.cls in ("PREP", "PRON_DEP")   # has its own complement
            self._set(i + 1, "PROPN" if nxt.cls == "PROPN" else "VERB" if participle else "NOUN", "GEN",
                      "اسم فاعل" if participle else "", rules=["R02"])
            return i + 2
        return i + 1

    def _noun_phrase(self, j, coord_fn=None, loose_spec=False):
        """Attributes, genitives and appositions after a head noun. Returns the first index after it."""
        n = len(self.t)
        while j < n and self._free(j):
            t, prev = self.t[j], self.t[j - 1]
            agrees = (prev.key or "")[-2:] in ("tj", "wt", "wj") and (prev.key or "")[-2:] == (t.key or "")[-2:]
            if t.key == "pw":                                           # v2 (cause 3): pw is a subject, not an attribute
                break
            if t.cls == "NUM":                                          # v7: mḥ 120 — a number follows its noun
                self._set(j, "NUM", "ATTR", rules=["R19"])
                j += 1
                continue
            if t.cls == "GENPART" and not self._prep_n(j):
                j = self._genitive(j)
            elif t.cls == "GENPART":
                break
            elif t.cls == "OPEN" and t.has_n and t.verbish() and (
                    prev.cls == "DEM" or (j + 1 < n and self.t[j + 1].cls == "PREP" and self.t[j + 1].has_pron)):
                # v5: NOUN + sḏm.n.f with a resumptive pronoun after it, or after a demonstrative = relative form
                # (ḫꜣst nbt rwt.n.j r.s · ẖnw ḫpr.n.k jm.f · tꜣ pn ḥḳꜣ.n.f)
                self._set(j, "VERB", "ATTR", "صيغة صلة", ["R32"])
                j += 1
                if j < n and self._free(j) and self.t[j].cls == "PREP" and self.t[j].has_pron:
                    self._set(j, "ADP", "ADVERBIAL", rules=["R32", "R24"])
                    j += 1
            elif t.cls == "REL":                                        # v2 (cause 1): rmṯ kmt ntjw jm ḥnꜥ.f
                self._set(j, "PRON", "ATTR", rules=["R37"])
                j += 1
                if j < n and self._free(j) and self.t[j].cls in ("ADV", "PREP"):
                    p = self.t[j]
                    self._set(j, p.entry["upos"] if p.cls == "ADV" else "ADP", "PRED", rules=["R37", "R03"])
                    j += 1
                    if p.cls == "PREP" and not p.has_pron and j < n and self._free(j):
                        self._set(j, self.t[j].nominal_upos(), "POBJ", rules=["R03"])
                        j += 1
            elif agrees and t.can_be("ADJ"):                            # R19 by concord: rwtj wrtj
                self._set(j, "ADJ", "ATTR", rules=["R19"])
                j += 1
            elif t.cls == "DEM" or (t.adjectival() and prev.cls != "PREP"):
                self._set(j, "PRON" if t.cls == "DEM" else "ADJ", "ATTR", rules=["R19"])
                j += 1
            elif t.cls == "PROPN" and self._genitive_name(prev, t):
                self._set(j, "PROPN", "GEN", rules=["R16"])
                j += 1
            elif t.cls in ("PROPN", "TITLE"):
                self._set(j, "PROPN" if t.cls == "PROPN" else "NOUN", "APPOS", rules=["R17"])
                j += 1
            elif self.out[j - 1] and self.out[j - 1]["fn"] == "ATTR" and self.out[j - 1]["upos"] == "ADJ" \
                    and (t.nounish() and (not t.can_be("VERB") or loose_spec and t.top_upos != "VERB")
                         or loose_spec and t.cls == "OPEN" and not t.sufs and t.can_be("NOUN")):
                # R20: wrt ḥswt · v2 (cause 10): after pw (jḳr sḫrw) a verb reading only blocks it when it is the top one
                self._set(j, "NOUN", "SPEC", rules=["R20"])
                j += 1
            elif t.cls == "OPEN" and t.key in ("jrj",):                 # R21 nisbe 'thereof'
                self._set(j, "ADJ", "ATTR", rules=["R21"])
                j += 1
            elif coord_fn and t.nounish() and not t.verbish():          # R22 unmarked coordination
                self._set(j, t.nominal_upos(), coord_fn, rules=["R22"])
                j += 1
            elif t.nounish() and not t.verbish() and prev.cls != "PREP" and not prev.has_pron:
                # a noun that already has a suffix pronoun cannot take a direct genitive (sb.n ḥm.f mšꜥ)
                self._set(j, t.nominal_upos(), "GEN", rules=["R16"])
                j += 1
            else:
                break
        return j

    # ---- what follows the core of a clause ---------------------------------------------------
    def _rest(self, j, complete):
        n = len(self.t)
        while j < n:
            if not self._free(j):
                j += 1
                continue
            t, prev = self.t[j], self.t[j - 1] if j else None
            if t.cls == "PREP":                                         # R24 / R25 / R27
                self._set(j, "ADP", "ADVERBIAL", rules=["R25" if "-" in (t.key or "") else "R24"])
                k = j + 1
                if t.has_pron:                                          # m-ḫt.f: the object is the suffix
                    j = k
                    continue
                if k < n and self._free(k):
                    nk = self.t[k]
                    nxt = self.t[k + 1] if k + 1 < n else None
                    if nk.can_be("VERB") and nxt is not None and nxt.cls == "PRON_DEP":   # R31: m jr sw
                        self._set(k, "VERB", "POBJ", "اسم فاعل", ["R31"])
                        self._set(k + 1, "PRON", "OBJ", rules=["R31"])
                        j = k + 2
                        continue
                    if t.key == "r" and nk.verbish() and not nk.has_pron:
                        self._set(k, "VERB", "POBJ", "مصدر", ["R27"])
                        if nk.key == "rdjt":
                            return self._causative(k)
                        if nxt is not None and self._free(k + 1) and (nxt.nounish() or nxt.adjectival()):
                            self._set(k + 1, "ADJ" if nxt.adjectival() else "NOUN", "OBJ", rules=["R27"])
                            j = self._noun_phrase(k + 2)
                            continue
                    else:
                        self._set(k, nk.nominal_upos(), "POBJ", rules=["R24"])
                    j = self._noun_phrase(k + 1)
                    continue
                j += 1
            elif t.cls == "NUM":                                        # v7: hrw 3
                self._set(j, "NUM", "ATTR", rules=["R19"])
                j += 1
            elif t.cls == "ADV":                                        # v2 (cause 5): jm «there», ḥr-m «why»
                self._set(j, t.entry["upos"], "ADVERBIAL", rules=["R25"])
                j += 1
            elif t.cls == "PRON_DEP" and self.out[j - 1] and self.out[j - 1]["upos"] == "VERB":
                self._set(j, "PRON", "OBJ", rules=["R10"])              # v6: n ḳmd.j sj · wḥm st
                j += 1
                if j < n and self._free(j) and not self.t[j - 2].has_pron and self.t[j].nounish():
                    self._set(j, self.t[j].nominal_upos(), "SUBJ", rules=["R10"])   # nn bs ṯw ꜥꜣmw
                    j = self._noun_phrase(j + 1)
            elif t.cls == "PART_ENCL":                                  # v2 (cause 5): swt, grt
                self._set(j, "PART", "PARTICLE", rules=["R04"])
                j += 1
            elif t.cls == "NEG":
                return self._negation(j)
            elif t.cls == "PART_INTRO":
                return self._clause(j)
            elif t.cls == "GENPART" and self._prep_n(j):                # v2 (cause 6): šm.n.j ḥnꜥ.f n wḥwt.f
                self._set(j, "ADP", "ADVERBIAL", rules=["R24"])
                if self._free(j + 1):
                    if self._sdmt(j + 1):                               # v7: n jjt / n ḫprt.f
                        self._set(j + 1, "VERB", "POBJ", "sḏmt.f", ["R24"])
                    else:
                        self._set(j + 1, self.t[j + 1].nominal_upos(), "POBJ", rules=["R24"])
                j = self._noun_phrase(j + 2)
            elif t.cls == "GENPART":
                j = self._genitive(j)
            elif t.key == "jrj" and not t.sufs and self.out[j - 1] \
                    and self.out[j - 1]["upos"] in ("NOUN", "PROPN"):                # R21: ḥrj jrj
                self._set(j, "ADJ", "ATTR", rules=["R21"])
                j += 1
            elif t.nounish() and self.out[j - 1] and self.out[j - 1]["fn"] == "ATTR" \
                    and set(self.out[j - 1]["rules"]) & {"R30", "R31"}:            # object of a participle
                self._set(j, t.nominal_upos(), "OBJ", rules=self.out[j - 1]["rules"])
                j = self._noun_phrase(j + 1)
            elif t.verbish() and (t.has_pron or t.has_n) and complete:  # a new (circumstantial) clause
                return self._verbal(j)
            elif t.verbish() and not t.has_pron and complete and prev is not None and prev.cls != "PREP" \
                    and self.out[j - 1] and self.out[j - 1]["fn"] in ("ADVERBIAL", "POBJ", "VERB_HEAD"):
                self._set(j, "VERB", "CIRC", "الفعل التام القديم", ["R12", "R14"])   # R14
                j += 1
            elif t.verbish() and not t.has_pron and prev is not None and self.out[j - 1] \
                    and self.out[j - 1]["fn"] in ("PRED", "POBJ", "SUBJ", "GEN"):
                self._set(j, "VERB", "ATTR", "اسم فاعل", ["R30"])           # R30
                j += 1
            elif t.cls == "OPEN" and not t.cands and prev is not None and self.out[j - 1] \
                    and self.out[j - 1]["fn"] == "VERB_HEAD":
                self._set(j, "ADV", "ADVERBIAL", rules=["R26"])            # R26
                j += 1
            elif t.nounish():
                if prev is not None and self.out[j - 1] and self.out[j - 1]["fn"] in ("PRED", "SUBJ", "POBJ", "OBJ", "GEN"):
                    k = self._noun_phrase(j)
                    if k == j:                                          # nothing matched: plain genitive
                        self._set(j, t.nominal_upos(), "GEN", rules=["R16"])
                        k = j + 1
                    j = k
                    continue
                self._set(j, t.nominal_upos(), "SUBJ", rules=["R03"])  # a new non-verbal clause
                k = self._noun_phrase(j + 1)
                if not self._pw_sentence(j, k):
                    self._predicate(k)
                return
            else:
                self._set(j, t.top_upos or "X", "UNKNOWN")
                j += 1

irab/retokenize.py:
"""Layer [1]: re-tokenization (PLAN.md §5ب).

Turns the image-based pieces of a source text (e.g. hieratic-sinuhe/sinuhe_A.json)
into linguistic words. The source file is only read, never written.

Usage (from the egyptian-irab folder):
    python -m irab.retokenize
"""
import json
import re
import sys
import unicodedata
from dataclasses import dataclass, field
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SOURCE = ROOT.parent / "hieratic-sinuhe" / "sinuhe_A.json"
LEXICON = ROOT / "data" / "lexicon" / "sinuhe_seed.json"
OUTPUT = ROOT / "data" / "words" / "sinuhe_R1-24.words.json"

GENITIVE_PARTICLES = {"n", "nt", "nw"}

# Suffixes after a dot (step 7). A list means the suffix is ambiguous and all readings are kept.
SUFFIXES = {
    "j": ["pron.1s"], "k": ["pron.2ms"], "ṯ": ["pron.2fs"], "f": ["pron.3ms"],
    "s": ["pron.3fs"], "sn": ["pron.3pl"], "tn": ["pron.2pl"],
    "tw": ["passive"], "kw": ["stative.1s"], "tj": ["stative.2s", "stative.3fs"],
    "n": ["sdm.n", "pron.1pl"],
}


def key(text):
    """Lookup key (step 1): NFC, no brackets, z = s, lower case. Never shown as the text itself."""
    t = unicodedata.normalize("NFC", text)
    t = re.sub(r"[()\[\]]", "", t)
    return t.replace("z", "s").lower()


@dataclass
class Seg:
    """A run of characters between spaces/hyphens inside one source piece."""
    text: str
    src: int
    line: int
    start: int
    end: int
    sep: str = None        # separator before this segment: '-', ' ' or None (first segment)
    boundary: str = None   # 'token' / 'line' when this segment starts a new source piece
    date: bool = False

    @property
    def stem(self):
        return key(self.text.split(".", 1)[0])

    @property
    def has_suffix(self):
        return "." in self.text


@dataclass
class Word:
    segs: list
    kind: str = "word"
    lemma: str = None
    alts: list = field(default_factory=list)
    flags: list = field(default_factory=list)


def load_source(path=SOURCE):
    with open(path, encoding="utf8") as f:
        return sorted(json.load(f), key=lambda x: x["id"])


def load_lexicon(path=LEXICON):
    with open(path, encoding="utf8") as f:
        entries = json.load(f)["entries"]
    index = {}
    for e in entries:
        for form in e["forms"]:
            parts = [key(p) for p in re.split(r"[\s\-]+", form)]
            index.setdefault(parts[0], []).append({"parts": parts, "lemma": e["lemma"], "kind": e["kind"]})
    return index


def segment(pieces):
    """Steps 1–3: one stream of segments over the whole text, remembering every boundary."""
    segs = []
    for piece in pieces:
        s = piece["translit_uni"]
        is_date = key(s).startswith("rnpt-sp")
        for m in re.finditer(r"[^\s\-]+", s):
            seg = Seg(m.group(), piece["id"], piece["line"], m.start(), m.end(), date=is_date)
            if segs:
                prev = segs[-1]
                if prev.src == piece["id"]:
                    between = s[prev.end:m.start()]
                else:
                    between = prev_text[prev.end:] + s[:m.start()]
                    seg.boundary = "line" if prev.line != piece["line"] else "token"
                seg.sep = "-" if "-" in between else " "
            segs.append(seg)
            prev_text = s
    return segs


def lexicon_matches(segs, i, index):
    """All lexicon entries that start at segment i (step 4). Crossing pieces and lines is allowed."""
    found = []
    for e in index.get(segs[i].stem, []):
        n = len(e["parts"])
        if i + n > len(segs):
            continue
        window = segs[i:i + n]
        if any(s.date for s in window):
            continue
        if all(s.stem == p for s, p in zip(window, e["parts"])) and not any(s.has_suffix for s in window[:-1]):
            found.append((n, e))
    return found


def hyphen_run(segs, i):
    j = i
    while j + 1 < len(segs) and segs[j + 1].sep == "-" and not segs[j + 1].date:
        j += 1
    return j - i + 1


def best_match(segs, i, index):
    found = lexicon_matches(segs, i, index)
    if not found:
        return 0, None, []
    n = max(f[0] for f in found)
    top = [e for k, e in found if k == n]
    lemmas = list(dict.fromkeys(e["lemma"] for e in top))
    return n, top[0], lemmas[1:]


def cover_run(segs, i, length, index):
    """Split a hyphen run only if lexicon entries cover all of it (step 4, reverse direction)."""
    out, k = [], i
    while k < i + length:
        n, e, _ = best_match(segs, k, index)
        if not n or k + n > i + length:
            return None
        out.append((k, n, e))
        k += n
    return out


def words_from(segs, index):
    words, i = [], 0
    while i < len(segs):
        seg = segs[i]
        if seg.date:  # step 3: the date is one unit
            j = i
            while j + 1 < len(segs) and segs[j + 1].src == seg.src:
                j += 1
            words.append(Word(segs[i:j + 1], kind="date"))
            i = j + 1
            continue

        run = hyphen_run(segs, i)
        n, entry, alts = best_match(segs, i, index)
        if n >= run:
            words.append(Word(segs[i:i + n], kind=entry["kind"], lemma=entry["lemma"], alts=alts))
            i += n
            continue

        cover = cover_run(segs, i, run, index) if n else None
        if cover and len(cover) > 1:
            for k, m, e in cover:
                words.append(Word(segs[k:k + m], kind=e["kind"], lemma=e["lemma"]))
            i += run
            continue

        # step 5: join by hyphen; a join across pieces without a lexicon entry needs review
        w = Word(segs[i:i + run])
        if any(s.boundary for s in w.segs[1:]):
            w.flags.append("hyphen_join_needs_review")
        if run == 1 and key(seg.text) in GENITIVE_PARTICLES:
            w.kind = "genitive_particle"
        words.append(w)
        i += run
    return words


def morph(text):
    """Step 7: stem + suffixes, the word itself stays whole."""
    stem, *sufs = text.split(".")
    parts = [{"m": stem, "type": "stem"}]
    for j, s in enumerate(sufs):
        k = key(s)
        if k == "":
            continue
        types = SUFFIXES.get(k, ["unknown"])
        if k == "n" and j < len(sufs) - 1:
            types = ["sdm.n"]  # a pronoun cannot be followed by another suffix
        parts.append({"m": "." + s, "type": types[0] if len(types) == 1 else types})
    return parts


def surface(segs):
    out = segs[0].text
    for s in segs[1:]:
        out += s.sep if s.sep == "-" else " "
        out += s.text
    return out


def to_json(words, index):
    rows, src_index = [], {}
    for w_id, w in enumerate(words, 1):
        flags = list(w.flags)
        text = surface(w.segs)
        if text.endswith("."):
            flags.append("truncated")
        if re.search(r"[\[\]]", text):
            flags.append("restored")
        if re.search(r"[()]", text):
            flags.append("unwritten_letters")
        if w.lemma is None and w.kind not in ("date", "genitive_particle"):
            flags.append("not_in_lexicon")
        src = []
        for s in w.segs:
            if src and src[-1]["id"] == s.src:
                src[-1]["span"][1] = s.end
            else:
                src.append({"id": s.src, "span": [s.start, s.end]})
            src_index.setdefault(s.src, [])
            if w_id not in src_index[s.src]:
                src_index[s.src].append(w_id)
        rows.append({
            "w_id": w_id, "surface": text, "key": key(text), "lemma": w.lemma, "kind": w.kind,
            "src": src, "lines": sorted({s.line for s in w.segs}),
            "morph": morph(w.segs[-1].text) if w.kind != "date" else [],
            "alts": w.alts, "flags": flags,
        })
    return rows, src_index


def run(source=SOURCE, lexicon=LEXICON):
    pieces = load_source(source)
    index = load_lexicon(lexicon)
    words = words_from(segment(pieces), index)
    rows, src_index = to_json(words, index)
    return pieces, rows, src_index


def main():
    pieces, rows, src_index = run()
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    doc = {
        "meta": {
            "source": "hieratic-sinuhe/sinuhe_A.json (قراءة بس)",
            "lexicon": "data/lexicon/sinuhe_seed.json",
            "spec": "PLAN.md §5ب",
            "pieces": len(pieces), "words": len(rows),
        },
        "words": rows,
        "src_index": {str(k): v for k, v in sorted(src_index.items())},
    }
    with open(OUTPUT, "w", encoding="utf8") as f:
        json.dump(doc, f, ensure_ascii=False, indent=1)
    sys.stdout.reconfigure(encoding="utf-8")
    print(f"{len(pieces)} pieces -> {len(rows)} words -> {OUTPUT.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
